"""Concise authored outlines, checked against the supplied textbook and course slides."""
def answer(title, chapter, keywords, *paragraphs, formulas=()):
    steps = [dict(lead='Ý chính cần trình bày.', text=p) for p in paragraphs]
    steps += [dict(lead=lead, formula=tex, text=explanation) for lead, tex, explanation in formulas]
    return dict(title=title, chapter=chapter, keywords=keywords.split('|'), steps=steps)

